    this.operator = document.getElementById('operator');
    this.result = document.getElementById('result');

    this.num1.value = '';
    this.num2.value = '';
    this.operator.value = '';
    this.result.value = '';
  }

  clickHandler() {
    const num1 = this.num1.value;
    const num2 = this.num2.value;
    const operator = this.operator.value;

    switch (operator) {
      case '+':
        this.result.value = (parseInt(num1) + parseInt(num2));
        break;
      case '-':
        this.result.value = (parseInt(num1) - parseInt(num2));
        break;
      case '*':
        this.result.value = (parseInt(num1) * parseInt(num2));
        break;
      case '/':
        if (num2!== '0') {
          this.result.value = (parseInt(num1) / parseInt(num2));
        } else {
          this.result.value = 'Error: Division by zero';
        }
        break;
      default:
        this.result.value = 'Invalid operator';
    }
  }
}

const calculator = new Calculator();

document.getElementById('calculate').addEventListener('click', calculator.clickHandler);
